sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {


    var bulk_tt = g_scratchpad.blkTskRelated;
	var host = g_scratchpad.host;	//MSSCUSTODY-5250
	var user_access = g_scratchpad.usr_access;	//MSSCUSTODY-5250
	var user_was_maker = g_scratchpad.hasWorkedAsMaker; //MSSCUSTODY-5250

    if (isLoading || newValue === '') {
        return;
    }

	// AssignTo Changes then the user will be notified by alert.
    // if (bulk_tt == 'Checker' || bulk_tt == 'Maker') {
    //     if (g_form.getValue('assigned_to') != '') {
    //         if ((newValue == '') || (newValue == g_user.userID)) {
    //             // nothing
    //         } else {
    //             alert('task is now assigned to' + g_form.getDisplayBox('assigned_to').value);
    //         }
    //     }
    // }

	//MSSCUSTODY-5250

	if(user_was_maker && bulk_tt == 'Checker'){
		return;
	}
	else if(user_access && (bulk_tt == 'Maker' || bulk_tt == 'Checker')){
		if (g_form.getValue('assigned_to') != '') {
            if ((newValue == '') || (newValue == g_user.userID)) {
                // do nothing
            } else {
                alert('Task is now assigned to ' + g_form.getDisplayBox('assigned_to').value);
				var url = host + "x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=active=true^bulk_id.numberISNOTEMPTY^GROUPBYbulk_id";	//Redirects to list view
                //var url = host + "x_hsb11_mss_c_proc_mss_custody_task_list.do?&sysparm_query=active=true^";
				top.window.location = url;
            }
        }
	}	
	else {
		return;
	}
}
